entries[198627] = { ["name"] = "Blut der Khanswache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 486 Vielseitigkeit\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass Euer Primärwert um 1146 erhöht wird und Euch selbst 2731 Rüstung sowie den nächsten Verbündeten 4 Rüstung gewährt wird. Hält 15 Sek. lang an.\nVerkaufspreis:" }
