entries[198651] = { ["name"] = "Schrottteil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (25)\n\"Spezialisierte Ingenieure können manchmal auch ein Schrottteil finden, wenn sie Bomben oder Tüfteleien benutzen. Sie können Haufen davon durchwühlen, um nützliche Materialien oder andere Dinge zu finden.\"\nVerkaufspreis:" }
