entries[198804] = { ["name"] = "Frosterfüllter Köder für Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der elementaren Essenz des Frosts erfüllt.\"\nVerkaufspreis:" }
entries[198805] = { ["name"] = "Erderfüllter Köder für Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der elementaren Essenz der Erde erfüllt.\"\nVerkaufspreis:" }
entries[198806] = { ["name"] = "Verfallerfüllter Köder für Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der Essenz des Verfalls erfüllt.\"\nVerkaufspreis:" }
entries[198807] = { ["name"] = "Titanenerfüllter Köder für Kreaturen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen auf den Dracheninseln verringert.\n\nKann nur im Freien auf den Dracheninseln verwendet werden.\n\"Ein aufreizender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit der Essenz der Titanen erfüllt.\"\nVerkaufspreis:" }
entries[198808] = { ["name"] = "Wächtervorquin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Dracthyr und ehrfürchtigen Ruf bei den Obsidianwächtern (Allianz) oder ehrfürchtigen Ruf bei den Dunkelkrallen (Horde).\nVerkaufspreis:\n\"Diese gepanzerten Vorquin wurden mit uralten Dracthyrmethoden ausgebildet und sind der Gipfel der berittenen taktischen Kriegsführung am Boden.\"\nVerkäufer:\nTreysh\nZone:\nVerbotene Insel\nKosten:\n\nVerkäufer:\nTethalash\nZone:\nValdrakken\nKosten:" }
