entries[198818] = { ["name"] = "Listige Schlammmaske", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein widerwärtiger Schleim, in dem eine Sonnenbrille steckt.\"" }
entries[198821] = { ["name"] = "Göttlicher Kuss von Ohn'ahra", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten" }
entries[198822] = { ["name"] = "Überlassener Ohunaaufklärer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk von den Ohn'ir. Diese Ohuna sind unverzichtbare Begleiter für die Drachenschuppenexpedition beim Erforschen neuer Horizonte.\"\nErfolg:\nWeckt mich\nKategorie:\nErkundung" }
entries[198824] = { ["name"] = "Dämmerschwingenohuna", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wenn Ihr in den Nachthimmel blickt und die Wolken an Euch vorbeirasen seht, erschreckt nicht. Es könnte einfach der scheue Dämmerschwingenohuna sein.\"\nVerkäuferin:\nCelestine Erntedank\nZone:\nKüste des Erwachens\nZone:\nEbenen von Ohn'ahra\nZone:\nAzurblaues Gebirge\nZone:\nThaldraszus\nKosten:\n1.000" }
entries[198825] = { ["name"] = "Zenetküken", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die schroffsten Winde beginnen mit einem Windstoß und einem Flattern.\"\nBeute:\nZenetei\nZone:\nEbenen von Ohn'ahra" }
entries[198827] = { ["name"] = "Magischer Schneeschlitten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Springt auf und fahrt Schlitten! (5 Min Abklingzeit)\nBenötigt Ruhmrang 26 bei den Tuskarr von Iskaara.\nBenötigt Ruhmrang 27 bei den Tuskarr von Iskaara.\n\"Steigt auf!\"" }
entries[198830] = { ["name"] = "Herbeigezauberter schmackhafter Schlüpflingschmaus", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Herbeigezauberter Nachtisch (1)\nBenutzen: Lockt einen freundlichen Welpling mit einem unangenehm matschigen, aber dennoch verlockenden Leckerli aus seinem Versteck." }
entries[198831] = { ["name"] = "Herbeigezauberter Schnee im Hörnchen", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Herbeigezauberter Nachtisch (1)\nBenutzen: Lecker!" }
entries[198832] = { ["name"] = "Herbeigezauberter Walrossmuffin", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Herbeigezauberter Nachtisch (1)\nBenutzen: Lecker...?" }
entries[198833] = { ["name"] = "Herbeigezauberter Festtagskuchen", ["text"] = "Einzigartig: Herbeigezauberter Nachtisch (1)\nBenutzen: Richtet einen wunderbaren Kuchen her, um einen bedeutenden Anlass zu feiern! (2 Min Abklingzeit)" }
entries[198834] = { ["name"] = "Bemalte Rindenstücke", ["text"] = "Questgegenstand\nEinzigartig\n\"Rindenähnliche Schriftrollenteile, die den Winterpelzfurbolgs gestohlen wurden.\"" }
entries[198836] = { ["name"] = "Bogenlichtvitalkorrektoren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Steckt in der Nähe eines gefallenen Verbündeten achtlos ein paar ausgefranste Drähte zusammen in einem verzweifelten Versuch, ihn zu schocken und mit 60% Gesundheit und 20% Mana ins Leben zurückzuholen. Kann im Kampf eingesetzt werden. Was könnte schon schiefgehen?\n\nKann nicht von Spielercharakteren über Stufe 70 verwendet werden. (10 Min Abklingzeit)\nBenötigt Ingenieurskunst der Dracheninseln (1)\n\"Dass sich jemand bei dem einen Stromschlag abholt, ist vorprogrammiert.\"\nVerkaufspreis:" }
entries[198837] = { ["name"] = "Kuriose Hautfetzen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Kürschnerei der Dracheninseln (25)" }
entries[198839] = { ["name"] = "Vorlage: Siegel der titanischen Einsicht", ["text"] = "Benutzen: Lehrt Euch, wie man ein Siegel der titanischen Einsicht herstellt.\nBenötigt Juwelierskunst der Dracheninseln\n(1)\nVerkaufspreis:" }
entries[198840] = { ["name"] = "Kalezitansammlung", ["text"] = "\"Selbst erfahrene Edelsteinschleifer verwechseln diesen zerbrechlichen Edelstein oft mit dem deutlich wertvolleren Malygit. Ihr hingegen lasst Euch nicht täuschen!\"\nVerkaufspreis:" }
entries[198841] = { ["name"] = "Großes Exemplar eines kuriosen Balgs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen der Dracheninseln um 2 zu erhöhen.\nBenötigt Kürschnerei der Dracheninseln (25)\n\"Ihr vermutet, dass es ein Weilchen dauern wird, bis Ihr noch mal solch ein erstaunliches Exemplar eines kuriosen Balgs zu Gesicht bekommt.\"" }
entries[198842] = { ["name"] = "Weitschreiterfeder", ["text"] = "Questgegenstand\n\"WIP DESCRIPTION\"" }
entries[198843] = { ["name"] = "Erkundernotizen zu den Smaragdgärten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf Eurer Karte die Position eines Schatzes auf den Ebenen von Ohn'ahra ein.\n\"Ich sah einen grünen Schimmer, als ich an einer der Höhlen in den Smaragdgärten vorbeiging. Es könnte ein wertvoller Edelstein sein! Oder nur ein weiterer schlafender Drache...\"" }
entries[198847] = { ["name"] = "Flugbrutchitin", ["text"] = "Questgegenstand\n\"Ein knackiger Happen und alles, was sich ein junges Entchen nur wünschen könnte.\"" }
entries[198848] = { ["name"] = "Flugbrutthorax", ["text"] = "Questgegenstand\n\"Hört das auch mal auf zu tropfen?\"" }
entries[198852] = { ["name"] = "Bärentötungsbefehle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf Eurer Karte die Position eines Schatzes in Thaldraszus ein.\n\"Die Bernsteine, nach denen wir gesucht haben, wurden in einer Höhle entdeckt. Leider scheint dies die Höhle eines ziemlich übellaunigen Bären zu sein. Erlegt ihn, damit wir endlich zu den Edelsteinen gelangen können.\"" }
entries[198854] = { ["name"] = "Artefaktaufzeichnungen des Archäologen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Zeichnet auf Eurer Karte die Position eines Schatzes an der Küste des Erwachens ein.\n\"Detaillierte Forschungsergebnisse, die auf einen möglichen Schatz nahe der Botschaft von Schwingenrast hinweisen.\"" }
entries[198855] = { ["name"] = "Wurfnetz", ["text"] = "Questgegenstand\nBenutzen: Auf Fischvorräte innerhalb von 15 Metern werfen. (5 Sek. Abklingzeit)\n\"Dieses Netz kann zum Fangen vieler Fische und zum Auffüllen des Angellochs benutzt werden.\"" }
entries[198856] = { ["name"] = "Flugbrutmandibeln", ["text"] = "Questgegenstand\n\"Für manche ist das der beste Teil.\"" }
entries[198857] = { ["name"] = "Duselente", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Eskortiert Duselente für kurze Zeit. Ihr wollt Lillistrazsa schließlich nicht enttäuschen, oder? (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[198858] = { ["name"] = "Energiegeladenes Arkanagefäß", ["text"] = "Questgegenstand\nEinzigartig\n\"Die verzauberte Aura, die das Gefäß umgibt, scheint zu schwinden.\"" }
entries[198859] = { ["name"] = "Offenbarendes Drachenauge", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Ermächtigt den Träger, in Valdrakken getarnte Primalisten innerhalb von 30 Metern zu sehen." }
