entries[198870] = { ["name"] = "Otto", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Entspannt Euch, die Zukunft wird ihren vorbestimmten Weg gehen... Otter etwa nicht?\"\nQuest:\nDer Weg zum Herzen eines Ottos" }
entries[198871] = { ["name"] = "Ottuk des Iskaarahändlers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Es gibt keine Garantie beim Kauf eines Ottuks von Tattukiaka. Immerhin sind sie niedlich.\"\nVerkäufer:\nTattukiaka\nZone:\nAzurblaues Gebirge\nKosten:\n1\n1" }
entries[198872] = { ["name"] = "Brauner Späherottuk", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 25 bei den Tuskarr von Iskaara.\n\n\"In ihrer natürlichen Umgebung sind Ottuks gewieft und verspielt und mit ihren scharfen Augen können sie auf große Entfernung nach Raubtieren Ausschau halten.\"\nFraktion:\nTuskarr von Iskaara\nRuhmstufe:\n25\nVerkäufer:\nTatto\nOrt:\nIskaara\nKosten:\n2\n2\n750" }
entries[198873] = { ["name"] = "Ottuk des Elfenbeinhändlers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Kein Erwachsener weiß, warum manche Ottuks weiß sind, doch jedes Tuskarrkind kann es Euch sagen: Sie essen einfach zu viel Schnee.\"\nVerkäufer:\nTattukiaka\nZone:\nAzurblaues Gebirge\nKosten:\n1\n1\n1" }
