entries[199062] = { ["name"] = "Karte für Rubinedelsteinklumpen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf Eurer Karte die Position eines Schatzes an der Küste des Erwachens ein.\n\"Vor langer Zeit wuchsen in den Rubinlebensbecken und den umliegenden Gebieten Rubinedelsteine. Bitte versucht, ein solches Vorkommen zu finden.\"" }
