entries[199065] = { ["name"] = "Bekümmerter Brief", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeichnet auf Eurer Karte die Position eines Schatzes im Azurblauen Gebirge ein.\n\"Nun, der Antrag wurde abgelehnt... Falls Ihr es zurückhaben möchtet, ich habe das Juwel in einen Kristallwasserfall geworfen, an dessen Grund er nun liegt.- Dongi\"" }
