entries[199197] = { ["name"] = "Abgefüllte Essenz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versorgt die Innovationsmaschine mit Energie, um einen Funken der Genialität zu erzeugen.\n\"Diese vor Energie nur so strotzende Essenz aktiviert die Innovationsmaschine in Valdrakken und dient zur Erschaffung eines einzigartigen Handwerksmaterials.\"" }
entries[199199] = { ["name"] = "Zähe Elchflanke", ["text"] = "Questgegenstand\n\"Ein bisschen zäh, aber vorzüglich für einen bei niedriger Temperatur gekochten Eintopf.\"" }
entries[199200] = { ["name"] = "Zartes Vorquinfleisch", ["text"] = "Questgegenstand\n\"In schön dicke Scheiben geschnitten ergibt dieses Fleisch köstliche Steaks.\"" }
entries[199201] = { ["name"] = "Zartes Vorquinfleisch", ["text"] = "Questgegenstand\n\"In schön dicke Scheiben geschnitten ergibt dieses Fleisch köstliche Steaks.\"" }
entries[199202] = { ["name"] = "Bedienstetenzeichen der Belobigung", ["text"] = "Saison 4 von Shadowlands\nWird beim Aufheben gebunden\nEinzigartig (12)\nVerkaufspreis:" }
entries[199203] = { ["name"] = "Phönixaschentalisman", ["text"] = "Wird beim Aufheben gebunden\n\"Nur jemand, der den Feuervogel wahrhaft verehrt hat, kann ein solch unvergessliches Erinnerungsstück herstellen.\"\nVerkaufspreis:" }
entries[199204] = { ["name"] = "Zerrissene widerstandsfähige Lederfetzen", ["text"] = "Verkaufspreis:" }
entries[199205] = { ["name"] = "Manasauger", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Ein seltener Fisch der sich von magischer Essenz ernährt. Kribbelt auf der Zunge.\"\nVerkaufspreis:" }
entries[199206] = { ["name"] = "Zerschmetterte Adamantschuppen", ["text"] = "Verkaufspreis:" }
entries[199207] = { ["name"] = "Eisrückengroppe", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Seine dichten Knochen werden von leichten Eiskristallen entlang des Rückens ausbalanciert.\"\nVerkaufspreis:" }
entries[199208] = { ["name"] = "Grungel", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Ein wahrhaft unscheinbarer Fisch.\"\nVerkaufspreis:" }
entries[199211] = { ["name"] = "Urzeitliche Essenz", ["text"] = "Wird an Kriegsmeute gebunden\n\"So alt wie Azeroth selbst. Kam durch extreme Elementaraktivität wieder zum Vorschein. Der Sturmjäger in der Nähe Eurer Hauptstadt könnte daran interessiert sein.\"" }
entries[199212] = { ["name"] = "Keulenfisch", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Schwer und stumpf. Wenn Ihr Euch je in einer Essensschlacht mit einem Tuskarr wiederfindet, achtet auf Keulenfische.\"\nVerkaufspreis:" }
entries[199213] = { ["name"] = "Lakkamukkrötenfisch", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Ein froschähnlicher Fisch mit magerem weißem Fleisch und kleinen, süßen Finnen.\"\nVerkaufspreis:" }
entries[199215] = { ["name"] = "Weltenbrechermitgliedschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ihr werdet ein Weltenbrecher sein... für kurze Zeit.\n\"Denkt daran, Eure Mitgliedschaft zu erneuern!\"\nVerkaufspreis:" }
