entries[199551] = { ["name"] = "Schnallengürtel der Einigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Erleuchtet legendär (1)\nTaille Kette\n113 Rüstung\n+66 [Beweglichkeit oder Intelligenz]\n+99 Ausdauer\nErhöht Eure Tempowertung um + 94.\nErhöht Eure Meisterschaftswertung um + 39.\nHaltbarkeit 70 / 70\nKlassen: Rufer\nAnlegen: 'Segen der Pakte' erhöht Euren Schaden und Eure Heilung passiv um zusätzlich 5.0%." }
entries[199552] = { ["name"] = "Erinnerung an Einigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nBenötigt Die Erleuchteten\n- Respektvoll\nBenötigt den Abschluss der Quest \"Verflochtene Seelen\" in Zereth Mortis.\n\nEinigkeit Runenschnitzmacht\n'Segen der Pakte' erhöht Euren Schaden und Eure Heilung passiv um zusätzlich 5.0%.\nRunenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\nBenötigt: Rufer" }
