entries[199802] = { ["name"] = "Formel: Werkzeug - Drakonische Finesse", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Drakonische Finesse' durchführt.\nEin Sammelwerkzeug dauerhaft verzaubern, sodass Eure Finesse um 24 erhöht wird. Kann nicht auf Gegenstände über Stufe 450 angewandt werden.\nBenötigt Verzauberkunst der Dracheninseln (25)\nBenötigt die Rufstufe \"Geschätzt\" beim Handwerkerkonsortium.\nVerkaufspreis:" }
