entries[199811] = { ["name"] = "Formel: Umhang - Anmutiges Ausweichen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Anmutiges Ausweichen' durchführt.\nEinen Umhang dauerhaft verzaubern, sodass die Vermeidung um 75 erhöht und der erlittene Fallschaden um 0% verringert werden. Kann nicht auf Gegenstände unter Stufe 10 angewandt werden.\nBenötigt Verzauberkunst der Dracheninseln (25)\nBenötigt Ruhmrang 9 bei der Drachenschuppenexpedition.\nVerkaufspreis:" }
