entries[199828] = { ["name"] = "Fußeimer der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nFüße Platte\n62 Rüstung\n+22 [Stärke oder Intelligenz]\n+33 Ausdauer\n+ 25 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 19.\nHaltbarkeit 65 / 65\nVerkaufspreis:" }
