entries[199830] = { ["name"] = "Trainingsattrappe der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört für 5 Min. eine Trainingsattrappe der Tuskarr am Zielort.\n\nKann nur im Freien verwendet werden. (1 Stunde Abklingzeit)\n\"Dicke Schichten aus zusammengebundenem Walleder, mit Stroh gefüllt. Diese Zielattrappe wurde hergestellt, um auch dem schärfsten Speer der Tuskarr zu widerstehen.\"\nVerkaufspreis:" }
entries[199831] = { ["name"] = "Vergessenes Drachenwappen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein verziertes Drachenwappen, dessen Herkunft und Geschichte längst vergessen sind.\"" }
entries[199832] = { ["name"] = "Geräucherte Meeresschlange", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Werft alle drei Fischarten in den Topf!\n\"Nicht giftig genug, um Euch zu töten... dennoch wird sie Eurer Suppe einen herzhaften Biss verleihen!\"\nVerkaufspreis:" }
entries[199833] = { ["name"] = "Drachenkopfaal", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Werft alle drei Fischarten in den Topf!\n\"Ihre Ernährung aus Feuergarnelen gibt dem Fleisch eine natürliche Schärfe.\"\nVerkaufspreis:" }
