entries[199886] = { ["name"] = "Handgelenksschützer der Tuskarrhaiwache", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Kette\n348 Rüstung\n+184 [Beweglichkeit oder Intelligenz]\n+415 Ausdauer\nErhöht Eure kritische Trefferwertung um + 187.\nErhöht Eure Meisterschaftswertung um + 144.\nHaltbarkeit 55 / 55\nBenötigt Ruhmrang 14 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[199887] = { ["name"] = "Armschienen des Tuskarrfallenstellers", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Leder\n236 Rüstung\n+184 [Beweglichkeit oder Intelligenz]\n+415 Ausdauer\nErhöht Eure kritische Trefferwertung um + 151.\nErhöht Eure Tempowertung um + 180.\nHaltbarkeit 55 / 55\nBenötigt Ruhmrang 14 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
