entries[199889] = { ["name"] = "Knochenplattenschulterstücke der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n720 Rüstung\n+245 [Stärke oder Intelligenz]\n+553 Ausdauer\nErhöht Eure kritische Trefferwertung um + 202.\nErhöht Eure Tempowertung um + 239.\nHaltbarkeit 100 / 100\nBenötigt Ruhmrang 22 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[199890] = { ["name"] = "Mantel des Tuskarrhandwerkers", ["text"] = "Wird beim Aufheben gebunden\nSchulter Stoff\n189 Rüstung\n+245 Intelligenz\n+553 Ausdauer\nErhöht Eure kritische Trefferwertung um + 192.\n+ 249 Vielseitigkeit\nHaltbarkeit 100 / 100\nBenötigt Ruhmrang 22 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[199891] = { ["name"] = "Schulterschützer der Tuskarrhaiwache", ["text"] = "Wird beim Aufheben gebunden\nSchulter Kette\n479 Rüstung\n+245 [Beweglichkeit oder Intelligenz]\n+553 Ausdauer\nErhöht Eure Tempowertung um + 230.\nErhöht Eure Meisterschaftswertung um + 211.\nHaltbarkeit 100 / 100\nBenötigt Ruhmrang 22 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[199892] = { ["name"] = "Reisesuppentopf der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erhöht die Vielseitigkeit von jedem in der Nähe um 1 und ermöglicht das Kochen. (5 Min Abklingzeit)\nBenötigt Ruhmrang 4 bei den Tuskarr von Iskaara." }
entries[199893] = { ["name"] = "Kostbare Steinfragmente", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Zerschmetterte Edelsteinfragmente aus einer größeren Juwelenfassung.\"" }
entries[199894] = { ["name"] = "Torheit des Fischers", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert den Korb für \"Torheit des Fischers\" auf dem Boden und fordert Eure Freunde heraus, zu sehen, wer den kleinen Fisch abbekommt. (1 Min Abklingzeit)\nBenötigt Ruhmrang 17 bei den Tuskarr von Iskaara." }
entries[199895] = { ["name"] = "Bruchstück einer Skulptur", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein großes Stück einer Skulptur... Das Motiv ist unbekannt.\"" }
entries[199896] = { ["name"] = "Gummiartiger Fischkopf", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört einen gummiartigen Fischkopf am Zielort, der 5 Min. lang als Zielattrappe dient.\n\nKann nur im Freien eingesetzt werden. (1 Stunde Abklingzeit)\nBenötigt Ruhmrang 17 bei den Tuskarr von Iskaara.\n\"Ein großes Nebenprodukt, das ordentlich was einstecken kann, passt aber auf den Geruch auf.\"" }
entries[199897] = { ["name"] = "Sitzsack mit blauem Bezug", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert den Sitzsack zu Euren Füßen. (5 Min Abklingzeit)\nBenötigt Ruhmrang 23 bei den Tuskarr von Iskaara.\nVerkaufspreis:" }
entries[199899] = { ["name"] = "Zugschlitten von Iskaara", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Zieht einen Tuskarrkinderschlitten, mit dem jemand fahren kann.\nBenötigt Ruhmrang 26 bei den Tuskarr von Iskaara.\nBenötigt Ruhmrang 27 bei den Tuskarr von Iskaara.\n\"Die Tuskarr sagen, wer den Schlitten für einen anderen zieht, ist eine Säule der Gemeinschaft... aber das hält die Kinder nicht davon ab, darüber zu streiten, wer darauf sitzen darf.\"" }
entries[199900] = { ["name"] = "Gebrauchte Vermessungsgeräte", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt Vermessungsausrüstung auf, damit es aussieht, als würdet Ihr gerade etwas sehr Wichtiges tun. (30 Min Abklingzeit)\n\"Hervorragend, um auszusehen, als wäre man mit etwas beschäftigt.\"\nVerkaufspreis:" }
entries[199901] = { ["name"] = "Extraktion: Erwecktes Feuer" }
entries[199902] = { ["name"] = "Kompass des Wegfinders", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Aktiviert den Kompass des Wegfinders, um Euch zu helfen, Euch auf der Welt zurechtzufinden. (30 Min Abklingzeit)" }
entries[199903] = { ["name"] = "Extraktion: Erweckter Frost" }
entries[199904] = { ["name"] = "Extraktion: Erweckte Luft" }
entries[199905] = { ["name"] = "Extraktion: Erweckte Erde" }
entries[199906] = { ["name"] = "Relikt der Titanen", ["text"] = "Wird beim Aufheben gebunden\n\"Das Relikt ist sehr alt und eindeutig titanischen Ursprungs. Es ist die Art von Relikt, um die Euch die führende Titanenforscherin Sorotis gebeten hat.\"" }
entries[199907] = { ["name"] = "Pläne der Rebellen", ["text"] = "Questgegenstand\n\"Sie erläutern die Pläne und Motivationen der mit den Primalisten verbündeten Rebellen.\"" }
entries[199915] = { ["name"] = "Uralter Obsidiananhänger", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein Anhänger, dessen Nutzen und Macht über die Zeit verloren gegangen ist.\"" }
entries[199916] = { ["name"] = "Rosenrothüpfer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[199917] = { ["name"] = "Drachenknochenfragment", ["text"] = "Questgegenstand\n\"Laut den Gnollen sind diese Knochen magisch. Für uns könnten die mutierten Knochen wertvoll sein.\"" }
entries[199918] = { ["name"] = "Honigpflaumenkuchen", ["text"] = "Questgegenstand\nEinzigartig\n\"Süß, sauer und köstlich.\"" }
entries[199919] = { ["name"] = "Yakmilchpudding", ["text"] = "Questgegenstand\nEinzigartig\n\"Sauer, süß und köstlich.\"" }
entries[199921] = { ["name"] = "Mantel der Schrottmeisterin", ["text"] = "Wird beim Aufheben gebunden\nRücken\n4 Rüstung\n+4 [Beweglichkeit oder Stärke oder Intelligenz]\n+6 Ausdauer\n+ 8 Vielseitigkeit\nAnlegen: Legt den Mantel der Schrottmeisterin an.\nVerkaufspreis:" }
entries[199924] = { ["name"] = "Starker Seetang", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig (3)\n\"Wird in Iskaara oft ans Ufer gespült. Bringt ihn zu Tavio.\"" }
entries[199925] = { ["name"] = "Stein mit Loch", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig (2)\n\"Nicht ungewöhnlich an den felsigen Küsten der Azurblauen Gebirges. Tavio in Iskaara weiß etwas damit anzufangen.\"" }
entries[199927] = { ["name"] = "Notenblatt: Die faule Rübe", ["text"] = "Benutzen:" }
entries[199928] = { ["name"] = "Flammenwerferfackel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Benutzt die Flammenwerferfackel, um 6 Sek. lang alle 0.3 Sek. 88219 Feuerschaden zu verursachen. (8 Sek. Abklingzeit)\n\"Verzaubert mit den Elementen der Luft und des Feuers. Diese Fackel teilt ordentlich aus. Richtet sie nicht auf Euer Gesicht.\"" }
entries[199930] = { ["name"] = "Eiskaltes Gegengift", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Flasche fühlt sich kalt an. Kaum zu glauben, dass das jemanden heilen soll.\"" }
entries[200061] = { ["name"] = "Prismatischer Springer", ["text"] = "Handwerksmaterial\n\"Die Schuppen schimmern in den verschiedensten Farben. Abgesehen von seinen Kocheigenschaften, scheint dieser Fisch auch mahlbar zu sein.\"\nVerkaufspreis:" }
entries[200063] = { ["name"] = "Rätsel für Aufmerksame: Leckerli", ["text"] = "Questgegenstand\nBenutzen: Werft einem besitzergreifenden Flunker ein \"Leckerli\" zu.\n\"Ein zweifelhaftes Häppchen für einen knurrigen Flunker.\"" }
entries[200064] = { ["name"] = "Preis der Marmoni", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert die Rätselzutaten zu einem dubiosen \"Leckerli\".\n70 ( 70)\n\"Eine schimmernde, gelbe Banane, zur Aufbewahrung versteckt.\"" }
entries[200065] = { ["name"] = "Verlorenes Seifenstück eines Abenteurers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert die Rätselzutaten zu einem dubiosen \"Leckerli\".\n70 ( 70)\n\"Ein notwendiger Gegenstand, den ein unvorsichtiger Abenteurer vor langer Zeit verloren hat.\"" }
entries[200066] = { ["name"] = "Gut erhaltener Knochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Kombiniert die Rätselzutaten zu einem dubiosen \"Leckerli\".\n70 ( 70)\n\"Ein trockenes, verkrustetes Knochenstück, das lange vor den Elementen geschützt wurde.\"" }
entries[200067] = { ["name"] = "Flüsternder Splitter", ["text"] = "Questgegenstand\n\"Der Splitter füllt flüsternd Euren Verstand mit vielen Komplimenten. Ihr seid ziemlich toll, oder?\"" }
entries[200069] = { ["name"] = "Obsidiantruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Gold, Vorräte der Dracheninseln, seltene Dracheninselartefakte und Relikte der Titanen sowie eine Chance auf kosmetische Djaradinwaffen und -rüstungen.\"\n<Zum Öffnen rechtsklicken>" }
entries[200070] = { ["name"] = "Obsidianschließkassette", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Gold, Vorräte der Dracheninseln, seltene Artefakte und Relikte sowie eine Chance auf kosmetische Djaradinwaffen und -rüstungen.\"\n<Zum Öffnen rechtsklicken>" }
entries[200071] = { ["name"] = "Heiliges Tuskarrtotem", ["text"] = "Wird beim Aufheben gebunden\n\"Wurde den Tuskarr von Iskaara gestohlen. Älteste Poa würde Euch belohnen, wenn Ihr es zurückbringt.\"" }
entries[200072] = { ["name"] = "Schließkassette der Drachenfluchfestung", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält geplünderte Gegenstände, Vorräte, Gold und Artefakte.\"\n<Zum Öffnen rechtsklicken>" }
entries[200073] = { ["name"] = "Schätze von Valdrakken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält über die Jahre angesammelte Ausrüstung, Vorräte und Schätze.\"\n<Zum Öffnen rechtsklicken>" }
entries[200074] = { ["name"] = "Gefrorener Raureifflossenthunfisch", ["text"] = "Benutzen: Wischt den Eisbelag von diesem Fisch.\nHandwerksmaterial\n\"Ein kräftiger Fisch mit einem gefrorenen Außenpanzer.\"\nVerkaufspreis:" }
entries[200075] = { ["name"] = "Knochen fliegender Fische", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig\n\"In Fischerdörfern wie Iskaara sollte es genug davon geben. Bringt sie zu Tavio.\"" }
entries[200076] = { ["name"] = "Harpunenspitze", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig\n\"Fähige Schmiede wie die Tuskarr von Iskaara sollten eine haben. Bringt sie zu Tavio in Iskaara.\"" }
entries[200077] = { ["name"] = "Holzstab", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig\n\"Sollte leicht in den Wäldern des westlichen azurblauen Gebirges zu finden sein. Bringt ihn zu Tavio in Iskaara.\"" }
entries[200078] = { ["name"] = "Spitzhackenkopf", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig\n\"Ihr könnt vielleicht einen in einem Lager der Drachenschuppenexpedition... \"ausleihen\", zum Beispiel am Dreifällerundblick. Bringt ihn zu Tavio in Iskaara.\"" }
entries[200079] = { ["name"] = "Wassergeschliffener Basalt", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird beim Aufheben gebunden\nEinzigartig (3)\n\"Gibt es dort reichlich, wo Lava auf das Meer trifft, wie an der Wilden Küste. Bringt ihn zu Tavio in Iskaara.\"" }
entries[200080] = { ["name"] = "Drakoniumnugget", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um das Fischernetz von Iskaara zu verbessern. Bringt es zu Tavio in Iskaara. Kann im Hochland, in Eislöchern oder in Lavapfützen der Dracheninseln geangelt werden.\"" }
entries[200081] = { ["name"] = "Starke Seeranke", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um die Harpune von Iskaara zu verbessern. Bringt es zu Tavio in Iskaara. Kann im Hochland, in Eislöchern oder in Lavapfützen der Dracheninseln geangelt werden.\"" }
entries[200082] = { ["name"] = "Zerfleddertes Imbunetz", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um das Fischernetz von Iskaara zu verbessern. Bringt es zu Tavio in Iskaara. Kann im Hochland, in Eislöchern oder in Lavapfützen der Dracheninseln geangelt werden.\"" }
entries[200083] = { ["name"] = "Eisenbaumzweig", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um die Harpune von Iskaara zu verbessern. Bringt es zu Tavio in Iskaara. Kann im Hochland, in Eislöchern oder in Lavapfützen der Dracheninseln geangelt werden.\"" }
entries[200084] = { ["name"] = "Salziges Serevit", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um die Harpune von Iskaara zu verbessern. Bringt es zu Tavio in Iskaara. Kann im Hochland, in Eislöchern oder in Lavapfützen der Dracheninseln geangelt werden.\"" }
entries[200085] = { ["name"] = "Khaz'goritdraht", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um das Fischernetz von Iskaara weiter zu verbessern. Bringt ihn zu Tavio in Iskaara. Kann mit dem Fischernetz gefangen werden.\"" }
entries[200086] = { ["name"] = "Khaz'goriterfülltes Harz", ["text"] = "Angelausrüstungsmaterial von Iskaara\nWird an Kriegsmeute gebunden\n\"Wird dazu verwendet, um Eure Harpune von Iskaara weiter zu verbessern. Bringt es zu Tavio in Iskaara. Kann mit einer Harpune von Iskaara von RIESIGEN Fischen der Dracheninseln erlangt werden.\"" }
entries[200087] = { ["name"] = "Wasserfallpartikel", ["text"] = "Questgegenstand\n\"Diese zähe Flüssigkeit lässt sich schwer halten.\"" }
entries[200093] = { ["name"] = "Jagdtrophäe der Zentauren", ["text"] = "Dracheninselartefakte\nWird beim Aufheben gebunden\n\"Kann bei Jagdausbilder Basku in Maruukai abgegeben werden, um Euren Ruf bei den Zentauren der Maruuk zu erhöhen.\"" }
entries[200094] = { ["name"] = "Karawanenschließkassette", ["text"] = "Wird beim Aufheben gebunden\n\"Klan Aylaag ist bekannt für seinen Handel, aber auch für seine Großzügigkeit denen gegenüber, die ihnen helfen. In seinen Schließkassetten sind wertvolle Ausrüstung, Artefakte und Handelsgüter zu finden.\"\n<Zum Öffnen rechtsklicken>" }
entries[200095] = { ["name"] = "Suppentopf mit Vorräten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Zeichen der Dankbarkeit. Dieser Topf ist voller Vorräte und Nahrung. Am Boden könnte sogar ein Artefakt oder Ausrüstungsteil zu finden sein.\"\n<Zum Öffnen rechtsklicken>" }
entries[200099] = { ["name"] = "V.I.F.", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Verzehrfertiges Instantfleisch.\"\nVerkaufspreis:" }
entries[200100] = { ["name"] = "Batubar der Unerbittliche", ["text"] = "Questgegenstand\n\"Als Waffe Maruuks tötete Batubar unzählige Dämonen, bevor die Ukhel seinen Geist für den Kampf wiedererweckten.\"" }
entries[200102] = { ["name"] = "Pläne: Wutentbrannte Legierung", ["text"] = "Benutzen: Lehrt Euch, wie man wutentbrannte Legierungen herstellt.\nBenötigt Schmiedekunst der Dracheninseln (25)\nVerkaufspreis:" }
entries[200103] = { ["name"] = "Muster: Wutentbrannter Balg", ["text"] = "Benutzen: Lehrt Euch, wie man wutentbrannte Bälge herstellt.\nEin mächtiges zornerfülltes Reagenz.\nBenötigt Lederverarbeitung der Dracheninseln (20)\nVerkaufspreis:" }
entries[200104] = { ["name"] = "Muster: Wutentbrannte Schuppen", ["text"] = "Benutzen: Lehrt Euch, wie man wutentbrannte Schuppen herstellt.\nEin mächtiges zornerfülltes Reagenz.\nBenötigt Lederverarbeitung der Dracheninseln (20)\nVerkaufspreis:" }
entries[200105] = { ["name"] = "Mit Moder bedecktes Treibgut", ["text"] = "Verkaufspreis:" }
