entries[200107] = { ["name"] = "Angelaufener Verlobungsring", ["text"] = "Verkaufspreis:" }
entries[200108] = { ["name"] = "Irideus' Energiekern", ["text"] = "Questgegenstand\n\"Aus den Hallen der Infusion. Dieses Gerät trieb einst den Hüter Irideus an.\"" }
entries[200109] = { ["name"] = "Heilsamer Trank", ["text"] = "Questgegenstand\n\"Die schimmernde Flüssigkeit im Inneren strahlt eine behagliche Wärme aus.\"" }
entries[200110] = { ["name"] = "Flüsternde Fragmente", ["text"] = "Questgegenstand\n\"Das Flüstern dieser Fragmente wird lauter, je mehr ihr sammelt. Vielleicht schadet es nicht, wenn Ihr ihnen ein wenig lauscht.\"" }
entries[200113] = { ["name"] = "Resonierender Kristall", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Verzauberkunst ausüben, indem sie Gegenstände entzaubern. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[200114] = { ["name"] = "Sturmie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[200115] = { ["name"] = "Sarantuya die Ewigwahre", ["text"] = "Questgegenstand\n\"Im Mondlicht wurden Assassinen auf Maruuk angesetzt. Im Mondlicht vereitelte Teera ihren Plan und tötete sie.\"" }
entries[200116] = { ["name"] = "Ewigwährendes Horn des Lavaschwimmens", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Trinkt aus diesem Horn, um im Freien auf den Dracheninseln für 10 Minuten immun gegenüber Lava zu sein. (30 Min Abklingzeit)\n\"Geht bloß nicht gerade schwimmen, wenn die Wirkung nachlässt.\"" }
entries[200117] = { ["name"] = "Goldener Gurt der Hüterin", ["text"] = "Questgegenstand\nEinzigartig\n\"Birgt viele mögliche Geheimnisse der Titanen über Metallarbeiten und vor allem... Mode.\"" }
